random.seed(1234)
cats = [None, "books", "food", "toys", "other"]
tiers = [None, "none", "", "silver", "platinum"]
coupons = [None, "WELCOME5", "HALFSHIP", "PCT0", "PCT5", "PCT7", "PCT30", "PCT99"]
prices = ["0.01", "0.05", "0.1", "1.005", "3.33", "9.99", "12.99", "0.005", "19.999", 10, 20, "123.45", 0, "-2.5"]

