    it = {"sku": f"S{i}", "price": random.choice(prices), "qty": random.choice([-3, -1, 0, 1, 2, 9, 10, 11, 25, 100])}
    c = random.choice(cats)
    if c is not None:
        it["category"] = c
    return it

n = 0
for _ in range(30000):
    cart = [rnd_item(i) for i in range(random.randint(0, 5))]
    cust = {}
    t = random.choice(tiers)
