        cust["tier"] = t
    cp = random.choice(coupons)
    try:
        a = legacy(cart, cust, cp)
        b = pricing.checkout(cart, cust, cp)
        ok = a == b
    except Exception as e:
        try:
            pricing.checkout(cart, cust, cp)
            ok = False
        except ValueError:
            ok = isinstance(e, ValueError)
        else:
            ok = False
    if not ok:
        print("MISMATCH", cart, cust, cp)
        print("legacy", a)
        print("new   ", b)
        raise SystemExit(1)
    n += 1
print("differential ok:", n)

# gold behaves like other tiers with 12%
r = pricing.checkout([{"sku": "G", "price": "100", "qty": 1}, {"sku": "H", "price": "100", "qty": 10}], {"tier": "gold"})
print(r)
assert r["lines"][0]["net"] == Decimal("88.00")
assert r["lines"][1]["net"] == Decimal("79.20")
print("gold ok")
